-- Importacao de lancamentos a partir de Gestao de Faturas (6).csv.
-- Relaciona cada linha por: Novo Contrato (ou Contrato) + Filial.
-- Quando houver mais de um contrato nessa combinacao, desempata por Servico, Identificador do item,
-- Produto Protheus, Centro de custo e Fornecedor.
-- Linhas sem contrato unico correspondente nao sao importadas; veja o SELECT final de pendencias.

create or replace function pg_temp.tmp_import_text_key(value text)
returns text
language sql
immutable
as $$
  select case
    when value is null then null
    when upper(btrim(value)) in ('', '-', 'N/A', 'NA', 'N.D.', 'ND', 'NÃO APLICA', 'NAO APLICA') then null
    else btrim(value)
  end
$$;

create or replace function pg_temp.tmp_import_norm(value text)
returns text
language sql
immutable
as $$
  select btrim(regexp_replace(
    translate(
      lower(coalesce(value, '')),
      'áàãâäéèêëíìîïóòõôöúùûüçñ',
      'aaaaaeeeeiiiiooooouuuucn'
    ),
    '[^a-z0-9]+',
    ' ',
    'g'
  ))
$$;

create or replace function pg_temp.tmp_import_text_matches(left_value text, right_value text)
returns boolean
language sql
immutable
as $$
  select case
    when pg_temp.tmp_import_norm(left_value) = '' or pg_temp.tmp_import_norm(right_value) = '' then false
    when pg_temp.tmp_import_norm(left_value) = pg_temp.tmp_import_norm(right_value) then true
    when position(pg_temp.tmp_import_norm(left_value) in pg_temp.tmp_import_norm(right_value)) > 0 then true
    when position(pg_temp.tmp_import_norm(right_value) in pg_temp.tmp_import_norm(left_value)) > 0 then true
    else false
  end
$$;

create or replace function pg_temp.tmp_import_fornecedor_matches(left_value text, right_value text)
returns boolean
language sql
immutable
as $$
  with aliases(alias, canonico) as (
    values
      ('claro', 'claro_embratel'),
      ('embratel', 'claro_embratel'),
      ('claro embratel', 'claro_embratel'),
      ('vivo', 'vivo_telefonica'),
      ('telefonica', 'vivo_telefonica'),
      ('vivo telefonica', 'vivo_telefonica'),
      ('telefonica vivo', 'vivo_telefonica'),
      ('algar', 'algar'),
      ('algar telecom', 'algar'),
      ('ingram', 'ingram'),
      ('ingram micro', 'ingram'),
      ('synnex', 'synnex'),
      ('td synnex', 'synnex'),
      ('mercanet', 'mercanet'),
      ('totvs', 'totvs')
  ),
  entrada as (
    select
      pg_temp.tmp_import_norm(left_value) as left_norm,
      pg_temp.tmp_import_norm(right_value) as right_norm
  ),
  canonicos as (
    select
      coalesce(
        (select canonico from aliases, entrada where entrada.left_norm = aliases.alias or position(aliases.alias in entrada.left_norm) > 0 order by length(alias) desc limit 1),
        (select left_norm from entrada)
      ) as left_canonico,
      coalesce(
        (select canonico from aliases, entrada where entrada.right_norm = aliases.alias or position(aliases.alias in entrada.right_norm) > 0 order by length(alias) desc limit 1),
        (select right_norm from entrada)
      ) as right_canonico,
      left_norm,
      right_norm
    from entrada
  )
  select case
    when left_norm = '' or right_norm = '' then false
    when left_canonico = right_canonico then true
    else pg_temp.tmp_import_text_matches(left_value, right_value)
  end
  from canonicos
$$;

create temp table tmp_import_lancamentos_gestao_faturas_6 (
  row_num integer,
  filial_original text,
  filial_codigo text,
  competencia text,
  situacao text,
  fornecedor_nome text,
  servico text,
  servico_protheus text,
  contrato_original text,
  novo_contrato text,
  numero_nota text,
  valor numeric(14, 2),
  data_vencimento date,
  dia_vencimento_fixo text,
  prazo_dias text,
  numero_medicao text,
  numero_pedido text,
  solicitacao_fluig text,
  status_sharepoint text,
  data_envio date,
  responsavel_pendencia text,
  observacao text,
  anexos text,
  observacao_protheus text,
  criado text,
  centro_custo text,
  recibo_provisorio text,
  recebimento text
) on commit drop;

