create temp table tmp_import_lancamentos_resolucao on commit drop as
select
  tmp.*,
  match.contrato_id,
  match.fornecedor_id,
  match.filial_id,
  match.cnpj_usado,
  match.contrato_centro_custo,
  match.contrato_descricao_servico,
  match.contrato_produto_protheus,
  match.contrato_servico_protheus,
  match.valor_base_previsto,
  match.contrato_chave,
  match.regra_vinculo_id,
  match.criterio_vinculo,
  coalesce(match.regra_total, 0) as regra_total,
  coalesce(match.base_total, 0) as base_total,
  coalesce(match.servico_total, 0) as servico_total,
  coalesce(match.item_total, 0) as item_total,
  coalesce(match.final_total, 0) as final_total,
  coalesce(match.fornecedor_total, 0) as fornecedor_total,
  match.contratos_possiveis,
  case
    when match.contrato_chave is null then 'Novo Contrato e Contrato vazios'
    when nullif(btrim(tmp.filial_codigo), '') is null then 'Filial vazia'
    when match.regra_total = 1 then null
    when match.regra_total > 1 then 'Mais de uma regra manual encontrada para esta linha'
    when coalesce(match.base_total, 0) = 0 then 'Contrato nao encontrado para Contrato/Novo Contrato + Filial'
    when match.base_total = 1 then null
    when nullif(btrim(tmp.servico), '') is null then 'Mais de um contrato encontrado para Contrato/Novo Contrato + Filial; Servico vazio'
    when match.servico_total = 0 then 'Mais de um contrato encontrado para Contrato/Novo Contrato + Filial; nenhum bate com Servico'
    when match.servico_total = 1 then null
    when match.item_total = 1 then null
    when match.final_total = 0 then 'Mais de um contrato encontrado para Servico; nenhum desempate por Identificador do item/Produto Protheus/Centro de custo'
    when match.final_total = 1 then null
    when match.fornecedor_total = 0 then 'Mais de um contrato encontrado mesmo apos Produto Protheus/Centro de custo; nenhum bate com Fornecedor'
    when match.fornecedor_total > 1 then 'Mais de um contrato encontrado mesmo apos Produto Protheus/Centro de custo e Fornecedor'
    else null
  end as erro_importacao
from tmp_import_lancamentos_gestao_faturas_6 tmp
left join lateral (
  with chave as (
    select coalesce(
      pg_temp.tmp_import_text_key(tmp.novo_contrato),
      pg_temp.tmp_import_text_key(tmp.contrato_original)
    ) as contrato_chave
  ),
  base as (
    select
      cm.*,
      fo.nome_empresa as fornecedor_contrato_nome,
      null::bigint as regra_vinculo_id,
      null::integer as regra_prioridade,
      null::bigint as regra_rank
    from public.contratos_mensais cm
    join public.fornecedores fo
      on fo.id = cm.fornecedor_id
    join public.filiais fl
      on fl.id = cm.filial_id
    cross join chave
    where pg_temp.tmp_import_text_key(cm.contrato_usado) = chave.contrato_chave
      and fl.codigo = tmp.filial_codigo
  ),
  regras_candidatas as (
    select
      cm.*,
      fo.nome_empresa as fornecedor_contrato_nome,
      regra.id as regra_vinculo_id,
      regra.prioridade as regra_prioridade,
      dense_rank() over (order by regra.prioridade desc) as regra_rank
    from public.contrato_vinculo_regras regra
    join public.contratos_mensais cm
      on cm.id = regra.contrato_id
    join public.fornecedores fo
      on fo.id = cm.fornecedor_id
    cross join chave
    where regra.ativo = true
      and pg_temp.tmp_import_text_key(regra.contrato_importacao) = chave.contrato_chave
      and pg_temp.tmp_import_text_key(regra.filial_codigo) = pg_temp.tmp_import_text_key(tmp.filial_codigo)
      and (
        pg_temp.tmp_import_text_key(regra.fornecedor_importacao) is null
        or pg_temp.tmp_import_fornecedor_matches(regra.fornecedor_importacao, tmp.fornecedor_nome)
      )
      and (
        pg_temp.tmp_import_text_key(regra.identificador_item_importacao) is null
        or pg_temp.tmp_import_text_matches(regra.identificador_item_importacao, tmp.servico)
        or pg_temp.tmp_import_text_matches(regra.identificador_item_importacao, tmp.observacao)
        or pg_temp.tmp_import_text_matches(regra.identificador_item_importacao, tmp.observacao_protheus)
      )
      and (
        pg_temp.tmp_import_text_key(regra.servico_importacao) is null
        or pg_temp.tmp_import_text_matches(regra.servico_importacao, tmp.servico)
      )
      and (
        pg_temp.tmp_import_text_key(regra.servico_protheus_importacao) is null
        or pg_temp.tmp_import_text_matches(regra.servico_protheus_importacao, tmp.servico_protheus)
      )
      and (
        pg_temp.tmp_import_text_key(regra.centro_custo_importacao) is null
        or pg_temp.tmp_import_text_key(regra.centro_custo_importacao) = pg_temp.tmp_import_text_key(tmp.centro_custo)
      )
      and (
        pg_temp.tmp_import_text_key(regra.dia_vencimento) is null
        or pg_temp.tmp_import_text_key(regra.dia_vencimento) = pg_temp.tmp_import_text_key(tmp.dia_vencimento_fixo)
      )
      and (
        regra.valor_referencia is null
        or (
          tmp.valor is not null
          and tmp.valor between
            regra.valor_referencia * (1 - (regra.tolerancia_valor_percentual / 100))
            and regra.valor_referencia * (1 + (regra.tolerancia_valor_percentual / 100))
        )
      )
  ),
  regras_top as (
    select *
    from regras_candidatas
    where regra_rank = 1
  ),
  por_servico as (
    select base.*
    from base
    where pg_temp.tmp_import_text_matches(base.descricao_servico, tmp.servico)
       or pg_temp.tmp_import_text_matches(base.nome_contrato, tmp.servico)
       or pg_temp.tmp_import_text_matches(base.detalhe, tmp.servico)
  ),
  por_identificador_item as (
    select por_servico.*
    from por_servico
    where pg_temp.tmp_import_text_matches(por_servico.subcontrato_nome, tmp.servico)
       or pg_temp.tmp_import_text_matches(por_servico.subcontrato_nome, tmp.observacao)
       or pg_temp.tmp_import_text_matches(por_servico.subcontrato_nome, tmp.observacao_protheus)
       or pg_temp.tmp_import_text_matches(por_servico.detalhe, tmp.servico)
  ),
  base_produto_centro as (
    select *
    from por_identificador_item
    where (select count(*) from por_identificador_item) > 0

    union all

    select *
    from por_servico
    where (select count(*) from por_identificador_item) = 0
  ),
  por_produto_centro as (
    select base_produto_centro.*
    from base_produto_centro
    where (
        pg_temp.tmp_import_text_key(tmp.servico_protheus) is null
        or pg_temp.tmp_import_text_matches(base_produto_centro.produto_protheus, tmp.servico_protheus)
        or pg_temp.tmp_import_text_matches(base_produto_centro.servico_protheus, tmp.servico_protheus)
      )
      and (
        pg_temp.tmp_import_text_key(tmp.centro_custo) is null
        or pg_temp.tmp_import_text_key(base_produto_centro.centro_custo_usado) = pg_temp.tmp_import_text_key(tmp.centro_custo)
      )
  ),
  por_fornecedor as (
    select por_produto_centro.*
    from por_produto_centro
    where pg_temp.tmp_import_text_key(tmp.fornecedor_nome) is null
       or pg_temp.tmp_import_fornecedor_matches(por_produto_centro.fornecedor_contrato_nome, tmp.fornecedor_nome)
       or pg_temp.tmp_import_fornecedor_matches(por_produto_centro.nome_contrato, tmp.fornecedor_nome)
  ),
  stats as (
    select
      chave.contrato_chave,
      (select count(*) from base) as base_total,
      (select count(*) from regras_top) as regra_total,
      (select count(*) from por_servico) as servico_total,
      (select count(*) from por_identificador_item) as item_total,
      (select count(*) from por_produto_centro) as final_total,
      (select count(*) from por_fornecedor) as fornecedor_total,
      (select string_agg(id::text, ', ' order by id) from base) as base_ids,
      (select string_agg((id::text || ' via regra ' || regra_vinculo_id::text), ', ' order by id) from regras_top) as regra_ids,
      (select string_agg(id::text, ', ' order by id) from por_servico) as servico_ids,
      (select string_agg(id::text, ', ' order by id) from por_identificador_item) as item_ids,
      (select string_agg(id::text, ', ' order by id) from por_produto_centro) as final_ids,
      (select string_agg(id::text, ', ' order by id) from por_fornecedor) as fornecedor_ids
    from chave
  ),
  escolhido as (
    select 'regra_manual' as criterio_vinculo, regras_top.*
    from regras_top
    cross join stats
    where stats.regra_total = 1

    union all

    select 'contrato_filial' as criterio_vinculo, base.*
    from base
    cross join stats
    where stats.regra_total = 0
      and stats.base_total = 1

    union all

    select 'servico' as criterio_vinculo, por_servico.*
    from por_servico
    cross join stats
    where stats.regra_total = 0
      and stats.base_total > 1
      and stats.servico_total = 1

    union all

    select 'identificador_item' as criterio_vinculo, por_identificador_item.*
    from por_identificador_item
    cross join stats
    where stats.regra_total = 0
      and stats.base_total > 1
      and stats.servico_total > 1
      and stats.item_total = 1

    union all

    select 'produto_centro' as criterio_vinculo, por_produto_centro.*
    from por_produto_centro
    cross join stats
    where stats.regra_total = 0
      and stats.base_total > 1
      and stats.servico_total > 1
      and stats.final_total = 1

    union all

    select 'fornecedor' as criterio_vinculo, por_fornecedor.*
    from por_fornecedor
    cross join stats
    where stats.regra_total = 0
      and stats.base_total > 1
      and stats.servico_total > 1
      and stats.final_total > 1
      and stats.fornecedor_total = 1
  )
  select
    escolhido.id as contrato_id,
    escolhido.fornecedor_id,
    escolhido.filial_id,
    escolhido.cnpj_usado,
    escolhido.centro_custo_usado as contrato_centro_custo,
    escolhido.descricao_servico as contrato_descricao_servico,
    escolhido.produto_protheus as contrato_produto_protheus,
    escolhido.servico_protheus as contrato_servico_protheus,
    escolhido.valor_base_previsto,
    stats.contrato_chave,
    escolhido.regra_vinculo_id,
    escolhido.criterio_vinculo,
    stats.regra_total,
    stats.base_total,
    stats.servico_total,
    stats.item_total,
    stats.final_total,
    stats.fornecedor_total,
    case
      when stats.regra_total > 0 then stats.regra_ids
      when stats.base_total <= 1 then stats.base_ids
      when stats.servico_total <= 1 then stats.servico_ids
      when stats.item_total <= 1 then stats.item_ids
      when stats.final_total <= 1 then stats.final_ids
      else stats.fornecedor_ids
    end as contratos_possiveis
  from stats
  left join escolhido on true
) match on true;

insert into public.lancamentos (
  contrato_id,
  competencia,
  filial_id,
  fornecedor_id,
  cnpj_usado,
  contrato_usado,
  centro_custo_usado,
  numero_nota,
  serie,
  valor,
  valor_previsto,
  data_envio,
  data_vencimento,
  descricao_servico,
  servico_protheus,
  numero_medicao,
  numero_pedido,
  solicitacao_fluig,
  observacao,
  etapa,
  status_pagamento,
  arquivo_nota,
  arquivo_boleto,
  repetir_por
)
select
  r.contrato_id,
  nullif(r.competencia, ''),
  r.filial_id,
  r.fornecedor_id,
  r.cnpj_usado,
  r.contrato_chave,
  coalesce(nullif(r.centro_custo, ''), r.contrato_centro_custo),
  nullif(r.numero_nota, ''),
  'U',
  coalesce(r.valor, 0),
  coalesce(r.valor_base_previsto, r.valor),
  r.data_envio,
  r.data_vencimento,
  coalesce(nullif(r.servico, ''), r.contrato_descricao_servico),
  coalesce(nullif(r.servico_protheus, ''), r.contrato_produto_protheus, r.contrato_servico_protheus),
  nullif(r.numero_medicao, ''),
  nullif(r.numero_pedido, ''),
  nullif(r.solicitacao_fluig, ''),
  concat_ws(' | ',
    nullif(r.observacao, ''),
    nullif(r.observacao_protheus, ''),
    case when nullif(r.situacao, '') is not null then 'Situacao: ' || r.situacao end,
    case when nullif(r.responsavel_pendencia, '') is not null then 'Responsavel pendencia: ' || r.responsavel_pendencia end,
    case when nullif(r.recebimento, '') is not null then 'Recebimento: ' || r.recebimento end,
    case when nullif(r.recibo_provisorio, '') is not null then 'RPS: ' || r.recibo_provisorio end,
    'Carga CSV Gestao de Faturas (6)'
  ),
  case
    when lower(coalesce(r.status_sharepoint, '')) like '%conclu%' then 'concluida'
    when lower(coalesce(r.status_sharepoint, '')) like '%conting%' then 'contingencia'
    when lower(coalesce(r.status_sharepoint, '')) like '%analise%'
      or lower(coalesce(r.status_sharepoint, '')) like '%análise%'
      or lower(coalesce(r.status_sharepoint, '')) like '%nota recebida%' then 'em_analise'
    else 'pendente'
  end,
  case
    when lower(coalesce(r.status_sharepoint, '')) like '%conclu%' then 'Concluída'
    when lower(coalesce(r.status_sharepoint, '')) like '%conting%' then 'Aguardando Contingência Gerente'
    when lower(coalesce(r.status_sharepoint, '')) like '%analise%'
      or lower(coalesce(r.status_sharepoint, '')) like '%análise%'
      or lower(coalesce(r.status_sharepoint, '')) like '%nota recebida%' then 'Aguardando Aprovação Fluig'
    when lower(coalesce(r.status_sharepoint, '')) like '%aguardando%' then 'Pendente Fatura'
    else 'Pendente Nota'
  end,
  null,
  null,
  1
from tmp_import_lancamentos_resolucao r
where r.erro_importacao is null
  and not exists (
    select 1
    from public.lancamentos l
    where l.contrato_id = r.contrato_id
      and l.competencia is not distinct from nullif(r.competencia, '')
      and l.numero_nota is not distinct from nullif(r.numero_nota, '')
      and l.data_vencimento is not distinct from r.data_vencimento
  );

with resumo as (
  select
    count(*) as linhas_csv,
    count(*) filter (where erro_importacao is null) as linhas_com_contrato_unico,
    count(*) filter (where erro_importacao is not null) as linhas_com_pendencia
  from tmp_import_lancamentos_resolucao
),
resultado as (
  select
    0 as ordem,
    'RESUMO' as tipo,
    null::integer as row_num,
    format(
      'linhas_csv=%s | importaveis=%s | pendencias=%s',
      linhas_csv,
      linhas_com_contrato_unico,
      linhas_com_pendencia
    ) as erro_importacao,
    null::text as filial_original,
    null::text as filial_codigo,
    null::text as fornecedor_nome,
    null::text as contrato_original,
    null::text as novo_contrato,
    null::text as contrato_chave,
    null::bigint as regra_vinculo_id,
    null::text as criterio_vinculo,
    null::text as servico,
    null::text as servico_protheus,
    null::text as numero_nota,
    null::numeric(14, 2) as valor,
    null::date as data_vencimento,
    null::text as contratos_possiveis
  from resumo

  union all

  select
    1 as ordem,
    'PENDENCIA' as tipo,
    row_num,
    erro_importacao,
    filial_original,
    filial_codigo,
    fornecedor_nome,
    contrato_original,
    novo_contrato,
    contrato_chave,
    regra_vinculo_id,
    criterio_vinculo,
    servico,
    servico_protheus,
    numero_nota,
    valor,
    data_vencimento,
    contratos_possiveis
  from tmp_import_lancamentos_resolucao
  where erro_importacao is not null
)
select
  tipo,
  row_num,
  erro_importacao,
  filial_original,
  filial_codigo,
  fornecedor_nome,
  novo_contrato,
  contrato_original,
  contrato_chave,
  regra_vinculo_id,
  criterio_vinculo,
  servico,
  servico_protheus,
  numero_nota,
  valor,
  data_vencimento,
  contratos_possiveis
from resultado
order by ordem, row_num nulls first;
